Read this instrumented bubble sort and report the pass count, the comparison count and the exchange count it prints.
data <- [1, 2, 3, 4, 5, 6]
tests <- 0. moves <- 0. passes <- 0
REPEAT WHILE passes < LENGTH(data) - 1 {
  passes <- passes + 1. moved <- false
  FOR j FROM 0 TO LENGTH(data) - 2 - passes {
    tests <- tests + 1
    IF data[j] > data[j + 1] { SWAP data[j], data[j + 1]. moves <- moves + 1. moved <- true } }
  IF moved = false { BREAK } }
DISPLAY passes, tests, moves

Read this instrumented bubble sort on a reversed list and report the pass count, the comparison count and the exchange count it prints.
data <- [6, 5, 4, 3, 2, 1]
tests <- 0. moves <- 0. passes <- 0
REPEAT WHILE passes < LENGTH(data) - 1 {
  passes <- passes + 1. moved <- false
  FOR j FROM 0 TO LENGTH(data) - 2 - passes {
    tests <- tests + 1
    IF data[j] > data[j + 1] { SWAP data[j], data[j + 1]. moves <- moves + 1. moved <- true } }
  IF moved = false { BREAK } }
DISPLAY passes, tests, moves

Read this instrumented selection sort and report the pass count, the comparison count and the value it leaves at the front.
data <- [6, 5, 4, 3, 2, 1]
tests <- 0. passes <- 0
REPEAT passes + 1 < LENGTH(data) {
  passes <- passes + 1. best <- passes
  FOR j FROM passes + 1 TO LENGTH(data) - 1 {
    tests <- tests + 1
    IF data[j] < data[best] { best <- j } }
  SWAP data[passes], data[best] }
DISPLAY passes, tests, data[0]

Read this instrumented insertion sort and report the shift count, the test count and the value left at the last position.
data <- [1, 2, 3, 5, 4, 6]
tests <- 0. shifts <- 0
FOR i FROM 1 TO LENGTH(data) - 1 {
  held <- data[i]. j <- i - 1
  WHILE j >= 0 { tests <- tests + 1
    IF data[j] <= held { BREAK }
    data[j + 1] <- data[j]. shifts <- shifts + 1. j <- j - 1 }
  data[j + 1] <- held }
DISPLAY shifts, tests, data[LENGTH(data) - 1]

Read this instrumented fresh sweep and report the number of tests it makes and the pair it settles on.
data <- [1, 2, 3, 4, 5, 6, 7, 8, 9]
target <- 13. tests <- 0
FOR i FROM 0 TO LENGTH(data) - 1 {
  FOR j FROM i + 1 TO LENGTH(data) - 1 {
    tests <- tests + 1
    IF data[i] + data[j] = target { DISPLAY tests, data[i], data[j]. BREAK } } }
DISPLAY tests, "not found"

Read this instrumented sliding window and report the additions, the subtractions and the number of window totals it records.
data <- [2, 1, 5, 1, 3, 2, 4, 1]
width <- 3. total <- 0. adds <- 0. subs <- 0. windows <- 0
FOR i FROM 0 TO width - 1 { total <- total + data[i]. adds <- adds + 1 }
windows <- windows + 1
FOR i FROM width TO LENGTH(data) - 1 {
  total <- total - data[i - width]. subs <- subs + 1
  total <- total + data[i]. adds <- adds + 1. windows <- windows + 1 }
DISPLAY adds, subs, windows

Read this instrumented list that doubles its room whenever it fills, and report the moves it makes, the growths it performs and the room it ends with.
room <- 1. filled <- 0. moves <- 0. growths <- 0
FOR i FROM 1 TO 8 {
  IF filled = room { room <- room * 2. growths <- growths + 1
    FOR j FROM 0 TO filled - 1 { moves <- moves + 1 } }
  filled <- filled + 1 }
DISPLAY moves, growths, room
